data.make-configs.js:
const fs = require('fs'), {URL}=require('url');
for (const [name, env] of [['source','SOURCE_URI'], ['target','TARGET_URI'], ['backup','BACKUP_URI']]) {
  if (!process.env[env]) continue;
  const uri=new URL(process.env[env]);
  if(name==='target') uri.pathname='/';
  if (process.env[env]) fs.writeFileSync('/work/'+name+'.yml', 'uri: '+JSON.stringify(uri.toString())+'\n', {mode:0o600});
}
print('Private tool configuration prepared');

data.verify-rehearsal.js:
const fs = require('fs'), crypto = require('crypto');
const source='/work/source/kubiq', target=process.env.VERIFY_TARGET_DIR||'/work/restored/kubiq';
const files=fs.readdirSync(source).filter(x=>x.endsWith('.bson')).sort();
const report={version:'8.0.34',database:'kubiq',rehearsal:process.env.VERIFY_KIND!=='backup-restore',backupRestore:process.env.VERIFY_KIND==='backup-restore',collections:[]};
const stable=x=>Array.isArray(x)?x.map(stable):x&&typeof x==='object'?Object.fromEntries(Object.keys(x).sort().map(k=>[k,stable(x[k])])):x;
for(const file of files){
 const a=fs.readFileSync(source+'/'+file),b=fs.readFileSync(target+'/'+file);
 const hash=x=>crypto.createHash('sha256').update(x).digest('hex');
 if(hash(a)!==hash(b))throw Error('BSON comparison failed for '+file);
 let count=0,offset=0;while(offset<a.length){const len=a.readInt32LE(offset);if(len<5||offset+len>a.length)throw Error('Invalid BSON');offset+=len;count++;}
 const metadata=file.replace(/\.bson$/,'.metadata.json');
 const m=JSON.parse(fs.readFileSync(source+'/'+metadata)),n=JSON.parse(fs.readFileSync(target+'/'+metadata));
 const normalize=m=>({options:m.options||{},indexes:m.indexes.map(i=>({...i,key:Object.entries(i.key)})).sort((a,b)=>a.name.localeCompare(b.name))});
 if(JSON.stringify(stable(normalize(m)))!==JSON.stringify(stable(normalize(n))))throw Error('Index/options mismatch '+file);
 report.collections.push({name:file.slice(0,-5),documents:count,bsonSha256:hash(a),indexes:m.indexes.length});
}
if(files.length===0)throw Error('No BSON collections to verify');
report.totalDocuments=report.collections.reduce((n,c)=>n+c.documents,0);if(report.totalDocuments===0)throw Error('Unexpected empty database');report.passed=true;
fs.writeFileSync(process.env.VERIFY_REPORT||'/work/rehearsal-verification.json',JSON.stringify(report,null,2),{mode:0o600});print(JSON.stringify(report));

data.admin-control.js:
const c=new Mongo(process.env.TARGET_URI), a=c.getDB('admin');
const action=process.env.MONGODB_ACTION;
if(action==='pause-ttl'||action==='resume-ttl'){
 const result=a.runCommand({setParameter:1,ttlMonitorEnabled:action==='resume-ttl'});
 if(result.ok!==1)throw Error('TTL operation failed');print(JSON.stringify({action,ok:true}));
}else{
 const s=a.serverStatus(),p=a.runCommand({getParameter:1,ttlMonitorEnabled:1,maxIndexBuildMemoryUsageMegabytes:1});
 print(JSON.stringify({version:a.runCommand({buildInfo:1}).version,ttlMonitorEnabled:p.ttlMonitorEnabled,indexBuildMemoryMiB:p.maxIndexBuildMemoryUsageMegabytes,connections:s.connections.current,usingPerCpuCaches:s.tcmalloc?.usingPerCpuCaches??s.tcmalloc?.usingPerCPUCaches}));
}

data.auth-check.js:
const fs=require('fs'), {URL}=require('url');
const app=new Mongo(process.env.APP_URI),d=app.getDB('kubiq');
const name='_migration_auth_check_'+Date.now();
try{d.getCollection(name).insertOne({check:true});if(d.getCollection(name).countDocuments({check:true})!==1)throw Error('CRUD failed');}
finally{d.getCollection(name).drop();}
let unauth=false,badPassword=false,adminDenied=false;
try{new Mongo('mongodb://mongodb.mongodb-system.svc.cluster.local:27017/kubiq').getDB('kubiq').getCollection('users').findOne();}catch(e){unauth=e.code===13||e.code===18;}
try{const u=new URL(process.env.APP_URI);u.password='deliberately-invalid';new Mongo(u.toString()).getDB('kubiq').getCollection('users').findOne();}catch(e){badPassword=e.code===18;}
try{app.getDB('admin').createUser({user:'forbidden-migration-check',pwd:'not-used',roles:[]});}catch(e){adminDenied=e.code===13;}
if(!unauth||!badPassword||!adminDenied)throw Error('Authentication/privilege boundary check failed');
for(const col of ['apmspans','logs']){const i=d.getCollection(col).getIndexes().find(i=>i.expireAfterSeconds!==undefined);if(!i)throw Error('TTL index missing');if(d.runCommand({collMod:col,index:{name:i.name,expireAfterSeconds:i.expireAfterSeconds}}).ok!==1)throw Error('Retention privilege missing');}
const report={retentionIndexUpdates:true,appCrud:true,unauthenticatedDenied:unauth,wrongPasswordDenied:badPassword,appAdministrationDenied:adminDenied,fixtureCollectionRemoved:!d.getCollectionNames().includes(name)};
fs.writeFileSync('/work/auth-verification.json',JSON.stringify(report),{mode:0o600});print(JSON.stringify(report));

data.ensure-users.js:
const c=new Mongo(process.env.TARGET_URI),d=c.getDB('kubiq'),a=c.getDB('admin');
if(!d.getRole('kubiq_retention'))d.createRole({role:'kubiq_retention',privileges:[{resource:{db:'kubiq',collection:'apmspans'},actions:['collMod']},{resource:{db:'kubiq',collection:'logs'},actions:['collMod']}],roles:[]});
d.grantRolesToUser('kubiq_app',[{role:'kubiq_retention',db:'kubiq'}]);
a.updateUser('kubiq_backup',{roles:[{role:'read',db:'kubiq'}]});
print(JSON.stringify({appRole:'readWrite plus collMod on apmspans/logs only',backupRole:'read on kubiq only'}));
